import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 35 Stop thief!","description":"学习 不定式与目的，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 35 Stop thief!","description":"学习 不定式与目的，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 不定式与目的，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 34 Quick work","link":"/life/english/new-concept/book-2/unit-02/lesson-034"},"next":{"text":"第二册：实践与进步 · Lesson 36 Across the Channel","link":"/life/english/new-concept/book-2/unit-02/lesson-036"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 34 Quick work","link":"/life/english/new-concept/book-2/unit-02/lesson-034"},"next":{"text":"第二册：实践与进步 · Lesson 36 Across the Channel","link":"/life/english/new-concept/book-2/unit-02/lesson-036"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-035.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-035.md"}'),s={name:"life/english/new-concept/book-2/unit-02/lesson-035.md"};function i(l,e,r,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-35-stop-thief" tabindex="-1">第二册：实践与进步 · Lesson 35 Stop thief! <a class="header-anchor" href="#第二册-实践与进步-·-lesson-35-stop-thief" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 35 Stop thief!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>街头有人追赶小偷，旁人通过冷静行动帮助制止事件；练习过去动作与动作完成后的结果。本课的语言观察是：stopped to help 表停下原来活动去帮忙；stopped helping 则表示停止帮助。两种结构的动作先后和目的不同。完成学习后，请写三句街头事件说明，分清看到的事实和每个人采取的行动。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>thief</td><td>/θiːf/</td><td>n.</td><td>小偷</td><td>catch a thief</td></tr><tr><td>chase</td><td>/tʃeɪs/</td><td>v.</td><td>追赶</td><td>chase a suspect</td></tr><tr><td>brave</td><td>/breɪv/</td><td>adj.</td><td>勇敢的</td><td>a brave decision</td></tr><tr><td>escape</td><td>/ɪˈskeɪp/</td><td>v.</td><td>逃脱</td><td>escape from danger</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>run away — 逃跑</li><li>stop somebody from doing — 阻止某人做某事</li></ul><h2 id="语法讲解-不定式与目的" tabindex="-1">语法讲解：不定式与目的 <a class="header-anchor" href="#语法讲解-不定式与目的" aria-label="Permalink to &quot;语法讲解：不定式与目的&quot;">​</a></h2><p>to 加动词原形可以作某些动词的宾语、名词后的修饰语或表示目的的状语。表示目的时，执行不定式动作的人通常与主句主语一致；不一致时需明确另一个逻辑主语，如 for somebody to do。否定一般写 not to do。情态动词后、make/let 主动结构中通常用不带 to 的原形，不能因为看到两个动词就一律在中间加入 to。本课应用：stopped to help 表停下原来活动去帮忙；stopped helping 则表示停止帮助。两种结构的动作先后和目的不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>A cyclist stopped to help the shop assistant.</p></blockquote><p>一位骑车人停下来帮助店员。</p><p>stopped 是主线过去动作，to help 是目的状语，the shop assistant 为 help 的宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>stop to run 是停下别的事去跑；stop running 是不再跑。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>连读 stopped to help，stopped 末尾 /t/ 可不完全爆破，但不要额外加音节。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A cyclist stopped to help the shop assistant. The thief dropped a bag near the door. A witness called the police instead of joining the chase.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句街头事件说明，分清看到的事实和每个人采取的行动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：stopped 是主线过去动作，to help 是目的状语，the shop assistant 为 help 的宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：stop to run 是停下别的事去跑；stop running 是不再跑。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 to help/helping：She stopped her journey ___ the assistant.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to help</p><p><strong>解析：</strong> 停止行程的目的是帮助，使用目的不定式。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>证人做了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The witness called the police.</p><p><strong>解析：</strong> instead of 表示选择报警而没有加入追赶。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>翻译：He stopped running。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 他停止了跑步。</p><p><strong>解析：</strong> 动名词表示被停止的活动，不表示停下后开始跑。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：不定式与目的。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-034">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-036">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",i]]);export{u as __pageData,b as default};
